using System.Collections.Frozen;

namespace CatalogSvc;

public class ProductCatalog
{
    private readonly record struct ProductInfo(string Category, decimal Price);

    private readonly Dictionary<string, ProductInfo> _products = new(StringComparer.OrdinalIgnoreCase);

    // Reverse index: category → product codes (O(1) category lookup)
    private readonly Dictionary<string, List<string>> _categoryIndex =
        new(StringComparer.OrdinalIgnoreCase);

    // Frozen snapshots for optimized reads after Freeze() is called
    private FrozenDictionary<string, ProductInfo>? _frozenProducts;
    private FrozenDictionary<string, string[]>? _frozenCategoryIndex;

    public void AddProduct(string code, string category, decimal price)
    {
        if (_products.TryGetValue(code, out var existing))
        {
            // Remove from old category index if category changed
            if (!existing.Category.Equals(category, StringComparison.OrdinalIgnoreCase)
                && _categoryIndex.TryGetValue(existing.Category, out var oldList))
            {
                oldList.Remove(code);
                if (oldList.Count == 0)
                    _categoryIndex.Remove(existing.Category);
            }
        }

        _products[code] = new ProductInfo(category, price);

        if (!_categoryIndex.TryGetValue(category, out var list))
        {
            list = new List<string>();
            _categoryIndex[category] = list;
        }
        if (!list.Contains(code))
            list.Add(code);

        // Invalidate frozen snapshots on mutation
        _frozenProducts = null;
        _frozenCategoryIndex = null;
    }

    /// <summary>
    /// Freezes the catalog into read-optimized snapshots. Call after bulk loading is complete.
    /// </summary>
    public void Freeze()
    {
        _frozenProducts = _products.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenCategoryIndex = _categoryIndex
            .ToFrozenDictionary(
                kvp => kvp.Key,
                kvp => kvp.Value.ToArray(),
                StringComparer.OrdinalIgnoreCase);
    }

    public string? GetCategory(string code)
    {
        var lookup = (IReadOnlyDictionary<string, ProductInfo>?)_frozenProducts ?? _products;
        return lookup.TryGetValue(code, out var info) ? info.Category : null;
    }

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        var lookup = (IReadOnlyDictionary<string, ProductInfo>?)_frozenProducts ?? _products;
        decimal total = 0m;
        foreach (var code in codes)
        {
            if (lookup.TryGetValue(code, out var info))
                total += info.Price;
        }
        return total;
    }

    public List<string> GetProductsByCategory(string category)
    {
        if (_frozenCategoryIndex is not null)
            return _frozenCategoryIndex.TryGetValue(category, out var arr)
                ? new List<string>(arr)
                : [];

        return _categoryIndex.TryGetValue(category, out var list)
            ? new List<string>(list)
            : [];
    }
}

